<script setup lang="ts">
import { ref, watch } from "vue"; import { useAppStore } from "../stores/app.js"; import { errorMessage,type ApiStickerPack } from "../types";
const store=useAppStore();const packs=ref<ApiStickerPack[]>([]);const status=ref("准备加载表情包……");async function loadAssets(){if(!store.currentWorldId)return;status.value="正在读取表情包……";try{const result=await store.api.getStickerPacks(store.currentWorldId);packs.value=result.data??[];for(const pack of packs.value){const stickers=await store.api.getStickers(pack.id);pack._stickers=stickers.data??[]}status.value=`${packs.value.length} 个表情包`;}catch(e:unknown){status.value=errorMessage(e)}}watch(()=>store.currentWorldId,()=>void loadAssets(),{immediate:true});
</script>
<template><section class="asset-page"><header class="page-header"><div><p>收藏与素材</p><h1>表情相册</h1><span>把故事里有趣的瞬间，收进自己的小小相册。</span></div><div class="header-right"><small id="assets-status">{{status}}</small><button @click="loadAssets">刷新</button></div></header><div v-if="packs.length" class="pack-list"><article v-for="pack in packs" :key="pack.id" class="pack-card"><header><div class="pack-cover">✦</div><div><p>表情包</p><h2>{{pack.name}}</h2></div><span>{{(pack._stickers||[]).length}} 张</span></header><div class="sticker-grid"><figure v-for="sticker in (pack._stickers||[])" :key="sticker.id"><div><img :src="sticker.mediaRef" :alt="sticker.label" loading="lazy"/></div><figcaption>{{sticker.label}}</figcaption></figure></div></article></div><div v-else class="empty-state"><span>▱</span><strong>相册还是空的</strong><p>导入表情包后，收藏会显示在这里。</p></div></section></template>
