der-radius:20px;background:rgba(255,253,250,.56);color:#9b8f87}.empty-state span{font-size:30px;color:#d7967e}.empty-state strong{margin-top:12px;font-size:14px;color:#665951}.empty-state p{margin:6px 0 0;font-size:12px}@media(max-width:1100px){.sticker-grid{grid-template-columns:repeat(4,1fr)}.asset-page{padding:30px}}
